export const combined49GeneratorSource = "import assert from \"node:assert/strict\";\nimport { createHash } from \"node:crypto\";\nimport { existsSync, lstatSync, readFileSync, writeFileSync } from \"node:fs\";\nimport { mkdir } from \"node:fs/promises\";\nimport { join } from \"node:path\";\nimport { gzipSync } from \"node:zlib\";\nimport { Database } from \"bun:sqlite\";\n\n// The coordinator supplies the accepted committed49 SHA, extracts only that\n// archive into ./archive, and captures its exact hashes in archive-provenance.json.\n// There are deliberately no current-worktree imports or default source revision.\nconst hash = (value: Uint8Array | string) => createHash(\"sha256\").update(value).digest(\"hex\");\nconst approvedRevision = process.argv[2];\nassert.match(approvedRevision ?? \"\", /^[a-f0-9]{40}$/);\nconst runName = process.argv[3] ?? \"run_1\";\nassert.match(runName, /^run_[a-z0-9]+$/);\nconst scratch = import.meta.dir;\nassert.equal(lstatSync(scratch).mode & 0o777, 0o700);\nconst archive = join(scratch, \"archive\");\nconst provenance = JSON.parse(readFileSync(join(scratch, \"archive-provenance.json\"), \"utf8\"));\nassert.equal(provenance.sourceRevision, approvedRevision);\nassert.equal(provenance.schemaVersion, 49);\nassert.match(provenance.sourceTree, /^[a-f0-9]{40}$/);\nassert.equal(Bun.version, \"1.3.14\");\nfor (const path of [\"src/storage/state-store.ts\", \"package.json\", \"bun.lock\"]) {\n  assert.match(provenance.sha256[path], /^[a-f0-9]{64}$/);\n  assert.equal(hash(readFileSync(join(archive, path))), provenance.sha256[path]);\n}\nconst archivedPackage = JSON.parse(readFileSync(join(archive, \"package.json\"), \"utf8\"));\nconst installedZod = JSON.parse(readFileSync(join(archive, \"node_modules/zod/package.json\"), \"utf8\"));\nassert.equal(installedZod.version, archivedPackage.dependencies.zod);\n// Dynamic imports occur only after the required accepted-archive provenance.\nconst { StateStore } = await import(\"./archive/src/storage/state-store\");\nconst { initializeStatePaths, resolveStatePaths } = await import(\"./archive/src/storage/paths\");\nconst { AttachmentBlobStore } = await import(\"./archive/src/storage/attachment-store\");\nconst { createStoredAccountUsageSnapshot } = await import(\"./archive/src/domain/usage-metrics\");\nconst outputDirectory = join(scratch, runName);\nassert.equal(existsSync(outputDirectory), false, \"Never overwrite a captured run.\");\nawait mkdir(outputDirectory, { mode: 0o700 });\nconst paths = resolveStatePaths({ rootDirectory: join(outputDirectory, \"state\") });\nawait initializeStatePaths(paths);\nconst now = 1_900_000_000_000;\nconst store = new StateStore(paths, { now: () => now, resolveMachineTimeZone: () => \"UTC\" });\nconst snapshot = () => {\n  const reader = new Database(paths.database, { readonly: true, strict: true });\n  try {\n    const schema = reader.query(\"SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name\").all();\n    const tables = reader.query(\"SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name\").all() as { name: string }[];\n    const rows: Record<string, unknown[]> = {};\n    for (const { name } of tables) {\n      assert.match(name, /^[a-zA-Z0-9_]+$/);\n      rows[name] = reader.query(`SELECT * FROM \"${name}\"`).all()\n        .sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));\n    }\n    return { version: reader.query(\"PRAGMA user_version\").get(), schema, rows,\n      foreignKeys: reader.query(\"PRAGMA foreign_key_check\").all(), inspectionChanges: reader.query(\"SELECT total_changes() AS count\").get() };\n  } finally { reader.close(false); }\n};\nassert.deepEqual(snapshot().version, { user_version: 49 });\nconst originalMigrations = snapshot().rows.migrations;\nassert.equal(originalMigrations.length, 49);\nconst bootId = `boot_${\"9\".repeat(32)}`;\nconst daemonGeneration = store.nextDaemonGeneration(bootId);\nassert.equal(daemonGeneration, 1);\nconst daemon = { daemonGeneration, bootId };\nconst codexProfile0 = store.nextProfileGeneration(store.createProfile(\"Combined49 synthetic pins\").id);\nassert.equal(store.setProfileState(codexProfile0.id, codexProfile0.processGeneration, \"signed_in\", {\n  email: \"combined49-pins@example.com\", plan: \"Plus\",\n}), true);\nconst codexProfile = store.requireProfile(codexProfile0.id);\nconst codexAuthority = store.requireProviderAccountAuthority(codexProfile.id, \"codex\");\nconst session = store.upsertProviderSession({ providerAuthority: codexAuthority,\n  profileId: codexProfile.id, provider: \"codex\", providerThreadId: \"combined49-synthetic-pin-source\",\n  providerAccountKey: `v1:codex:${hash(\"combined49-pins@example.com\")}`,\n  title: \"Combined49 synthetic retained source\", preset: \"high\", fastEnabled: false, state: \"idle\" });\nconst blobBytes = new TextEncoder().encode(\"Synthetic combined49 retained attachment.\\n\");\nconst blob = await AttachmentBlobStore.forStatePaths(paths).put(\"text/plain\", blobBytes);\nassert.equal(blob.kind, \"stored\");\nif (blob.kind !== \"stored\") throw new Error(\"SYNTHETIC_BLOB_ADMISSION_FAILED\");\nconst reference = { digest: blob.value.digest, byteLength: blob.value.byteLength,\n  name: \"combined49.txt\", mediaType: \"text/plain\" as const };\nconst ownerRequest = { kind: \"session.send\" as const, session: session.id,\n  idempotencyKey: \"49000000-0000-4000-8000-000000000045\",\n  message: \"Synthetic retained original request; never dispatched.\", attachments: [reference] };\nconst owner = store.prepareOwnedSessionSendWithCustody({ request: ownerRequest, ...daemon });\nassert.equal(owner.state, \"input_required\");\nassert.equal(owner.custody.kind, \"mutation_owned\");\nconst ownerReplay = store.prepareOwnedSessionSendWithCustody({ request: ownerRequest, ...daemon });\nassert.equal(ownerReplay.replayed, true);\nassert.equal(ownerReplay.ownerDigest, owner.ownerDigest);\nassert.deepEqual(ownerReplay.custody, owner.custody);\nconst queueKey = \"49000000-0000-4000-8000-000000000047\";\nconst queueMessage = \"Synthetic sealed attached queue; never dispatched.\";\nconst reservation = store.reserveAttachmentIngress({ kind: \"session.queue\", sessionId: session.id,\n  idempotencyKey: queueKey, message: queueMessage, attachments: [reference], providerAuthority: codexAuthority, ...daemon });\nassert.equal(reservation.kind, \"reserved\");\nif (reservation.kind !== \"reserved\") throw new Error(\"SYNTHETIC_QUEUE_RESERVATION_MISSING\");\nconst queueInput = { sessionId: session.id, idempotencyKey: queueKey, message: queueMessage,\n  profileGeneration: codexAuthority.processGeneration, providerAuthority: codexAuthority,\n  attachments: [{ ...reference, canonicalMediaType: \"text/plain\" as const }] };\nconst queue = store.enqueueIdempotentWithResult({ ...queueInput,\n  attachmentReservation: { reservationId: reservation.reservationId, reservationDigest: reservation.reservationDigest, ...daemon } });\nassert.equal(queue.verification, \"sealed\");\nassert.equal(queue.queued.state, \"pending\");\nassert.equal(store.enqueueIdempotentWithResult(queueInput).replayed, true);\n\n// Synthetic control-plane identity ONLY: no OS process, PID inspection,\n// launch, signal, runtime writer, authentication read, or native acceptance.\nconst claudeProfile = store.createProfile(\"Combined49 synthetic released Claude custody\");\n// Reserve a sequence without a quota observation or provider call. Otherwise\n// the archived maintenance tail initializes this unused profile's counter on\n// first reopen; it is not immutable owner or process-custody evidence.\nconst unusedProfileUsageRevision = store.allocateNextUsageRevision(claudeProfile.id);\nassert.equal(unusedProfileUsageRevision, 1);\nconst claude1 = store.advanceProviderAccountProcessGeneration({ profileId: claudeProfile.id, provider: \"claude\", expectedProcessGeneration: 0 });\nconst claudeAuthority = store.advanceProviderAccountProcessGeneration({ profileId: claudeProfile.id, provider: \"claude\", expectedProcessGeneration: claude1.processGeneration });\nconst syntheticIdentity = { pid: 49049, pidDomain: \"darwin\" as const, procStart: \"SYNTHETIC-CONTROL-PLANE-NOT-OS-CUSTODY-49\" };\nconst claudeKey = { profileId: claudeProfile.id, providerThreadId: \"combined49-synthetic-released-child\", runtimeScope: \"managed\" as const };\nconst claimed = store.recordClaimedClaudeProcessAuthority({ ...claudeKey,\n  profileGeneration: claudeProfile.processGeneration, providerAuthority: claudeAuthority, identity: syntheticIdentity });\nconst advancedShadow = store.nextProfileGeneration(claudeProfile.id);\nconst releasing = store.beginClaudeProcessAuthorityRelease({ ...claudeKey,\n  identity: syntheticIdentity, expectedRevision: claimed.revision });\nconst released = store.completeClaudeProcessAuthorityRelease({ ...claudeKey,\n  identity: syntheticIdentity, expectedRevision: releasing.revision });\nassert.equal(claimed.profileGeneration, 0);\nassert.equal(advancedShadow.processGeneration, 1);\nassert.equal(claudeAuthority.processGeneration, 2);\nassert.equal(released.state, \"released\");\nassert.equal(released.profileGeneration, 0);\nassert.deepEqual(released.providerAuthority, claudeAuthority);\nassert.deepEqual(store.requireProviderAccountAuthority(claudeProfile.id, \"claude\"), claudeAuthority);\n\nconst fingerprint = hash(\"combined49-synthetic-usage-account\");\nconst payload = (tokens: number, usedPercent: number) => ({ usage: { summary: { lifetimeTokens: tokens,\n  peakDailyTokens: null, longestRunningTurnSec: null, currentStreakDays: null, longestStreakDays: null }, dailyUsageBuckets: null },\n  rateLimits: { primary: { limitId: \"codex\", limitName: \"Codex\", planType: \"plus\", rateLimitReachedType: null,\n    primary: { usedPercent, windowDurationMins: 300, resetsAt: now / 1_000 + 3_600 },\n    secondary: { usedPercent: 20, windowDurationMins: 10_080, resetsAt: now / 1_000 + 604_800 } },\n    byLimitId: null, resetCreditsAvailable: 0 } });\nconst first = createStoredAccountUsageSnapshot({ accountFingerprint: fingerprint, daemonGeneration,\n  providerGeneration: codexAuthority.processGeneration, observedAt: now - 30, receivedAt: now - 30,\n  sourceSequence: 1, previousPayload: null, providerPayload: payload(100, 10) });\nconst third = createStoredAccountUsageSnapshot({ accountFingerprint: fingerprint, daemonGeneration,\n  providerGeneration: codexAuthority.processGeneration, observedAt: now - 10, receivedAt: now - 10,\n  sourceSequence: 3, previousPayload: first, providerPayload: payload(300, 30) });\nstore.recordUsage(codexProfile.id, 1, now - 30, first, codexAuthority);\nstore.recordUsagePollFailure(codexProfile.id, fingerprint, 2, now - 20, codexAuthority);\nstore.recordUsage(codexProfile.id, 3, now - 10, third, codexAuthority);\nconst usageMetadata = ([ [\"usage_snapshot\", 1], [\"usage_snapshot\", 3], [\"usage_poll_failure\", 2], [\"usage_upload_anchor\", 1] ] as const)\n  .map(([scope, revision]) => {\n    const value = store.readCodexUsageAuthorityMetadata(scope, codexProfile.id, revision);\n    assert.equal(value.mode, \"mutation_authoritative\");\n    assert.deepEqual(value.authority, codexAuthority);\n    return { scope, revision, value };\n  });\nconst usageProjection = store.latestProviderUsage(codexAuthority.providerAccountId);\nassert.ok(usageProjection);\nconst beforeClose = snapshot();\nassert.deepEqual(beforeClose.rows.migrations, originalMigrations);\nassert.deepEqual(beforeClose.foreignKeys, []);\nassert.equal(beforeClose.rows.attachment_custody_slots.length, 1);\nassert.equal(beforeClose.rows.attachment_custody_sets.length, 2);\nassert.equal(beforeClose.rows.attachment_custody_members.length, 2);\nassert.equal(beforeClose.rows.session_send_owners.length, 1);\nassert.equal(beforeClose.rows.session_send_execution_claims.length, 0);\nassert.equal(beforeClose.rows.mutation_effect_evidence.length, 0);\nassert.equal(beforeClose.rows.queue_attachment_identities.length, 1);\nassert.equal(beforeClose.rows.message_attachments.length, 1);\nstore.close();\nconst reopened = new StateStore(paths, { now: () => now, resolveMachineTimeZone: () => \"UTC\" });\nassert.deepEqual(snapshot(), beforeClose);\nreopened.close();\nconst readonly = new StateStore(paths, { readonly: true });\nreadonly.close();\nassert.deepEqual(snapshot(), beforeClose);\nconst checkpoint = new Database(paths.database, { create: false, strict: true });\ncheckpoint.exec(\"PRAGMA wal_checkpoint(TRUNCATE)\");\ncheckpoint.close(false);\nconst databaseBytes = readFileSync(paths.database);\nassert.ok(databaseBytes.length <= 8 * 1_024 * 1_024);\nconst generatorSource = readFileSync(import.meta.path, \"utf8\");\nconst publicProvenance = {\n  sourceRevision: approvedRevision, sourceTree: provenance.sourceTree, schemaVersion: 49,\n  sha256: Object.fromEntries([\"src/storage/state-store.ts\", \"package.json\", \"bun.lock\"]\n    .map((path) => [path, provenance.sha256[path]])),\n  dependency: { name: \"zod\", version: installedZod.version },\n};\nconst metadata = { provenance: publicProvenance, generatorSha256: hash(generatorSource), bunVersion: Bun.version,\n  databaseSha256: hash(databaseBytes), databaseBytes: databaseBytes.length,\n  syntheticControlPlaneOnly: true, osCustodyProved: false, nativeProviderEffects: 0,\n  deterministicDatabaseBytes: false, randomnessNotice: \"Archived public APIs generate random IDs; hashes identify this captured output, not deterministic regeneration.\",\n  compatibilityNotice: \"Exact combined49 only; no52 integration or release claim.\",\n  daemon, codexProfile, codexAuthority, session, ownerRequest, owner, queue, reservation,\n  attachment: { reference, bytesBase64: Buffer.from(blobBytes).toString(\"base64\") },\n  claude: { key: claudeKey, identity: syntheticIdentity, identityIsSynthetic: true, claimed, advancedShadow, releasing, released,\n    unusedProfileUsageRevision, usageObservationRecorded: false },\n  usage: { first, third, metadata: usageMetadata, projection: usageProjection }, snapshot: beforeClose };\nwriteFileSync(join(outputDirectory, \"combined49-fixture.json\"), `${JSON.stringify(metadata, null, 2)}\\n`, { mode: 0o600, flag: \"wx\" });\nwriteFileSync(join(outputDirectory, \"combined49.sqlite.gz\"), gzipSync(databaseBytes), { mode: 0o600, flag: \"wx\" });\nconsole.log(JSON.stringify({ outputDirectory, schemaVersion: 49, sourceRevision: approvedRevision,\n  databaseSha256: metadata.databaseSha256, databaseBytes: databaseBytes.length,\n  generatorSha256: metadata.generatorSha256, liveSlots: 1, owners: 1, sealedQueues: 1,\n  claudeState: released.state, usageScopes: usageMetadata.length, archivedRwRoReopenUnchanged: true }));\n";
