export const combined49DatabaseBytes = (): Uint8Array => {
  if (createHash("sha256").update(combined49GeneratorSource).digest("hex") !== combined49Fixture.generatorSha256) {
    throw new Error("COMBINED49_GENERATOR_MISMATCH");
  }
  const bytes = gunzipSync(Buffer.from(gzipBase64, "base64"), { maxOutputLength: combined49Fixture.databaseBytes });
  if (bytes.byteLength !== combined49Fixture.databaseBytes
    || createHash("sha256").update(bytes).digest("hex") !== combined49Fixture.databaseSha256) {
    throw new Error("COMBINED49_FIXTURE_MISMATCH");
  }
  return bytes;
};
